# per-switch, not continuous: between switches drovr still owns the file.
xdg.configFile."drovr/config.toml" = {
  force = true;
  text = ''
    # pi, not opencode. pi's findings channel is a generated TypeScript
    # extension rather than an MCP server (pi ships no MCP client), and drovr
    # writes it per review pass — see cli/src/pi_extension.rs upstream.
    #
    review_agent = "pi"
    worktree = ${lib.boolToString (isDarwin || !isDesktop)}
  '' + lib.optionalString (hostname == "fujiwara") ''
    # The LAN address, not the tailnet one and not 0.0.0.0. This server has no
    # auth, so it is reachable unauthenticated from the whole LAN and from
    # every pod on this node's address; see the block above home.nix emits
    # this from. `serve_host = "100.94.172.21"` restores the tailnet-only bind.
    serve_host = "10.0.7.100"
  '' + lib.optionalString (hostname == "utsuho") ''
    # wg0, not the tailnet: still one interface whose peers authenticate by key.
    serve_host = "10.9.0.6"
  '' + ''
    # Reviews run on gemma, pinned explicitly rather than left to pi's own
    # default so this file says which model reviewed. LAST in the file because
    # a TOML table swallows every key after it — the top-level settings above
    # have to be emitted first.
    #
    # gemma returns a panel in seconds rather than minutes. That is the model
    # being fast, not a reviewer skipping the diff — read the findings, not
    # the wall clock. The delivery floor that used to reject exactly this is
    # gone (drovr f016dcc); it could not tell "did not read" from "reads
    # quickly" and so refused every review on a fast backend.
    #
    # glm-5.3 was tried instead and does not DELIVER: measured 2026-09-02 on
    # a 278-line diff, four fresh iterations, sixteen reviewers, every one
    # provably started (pi extension loaded, seed delivered), worked 8-25
    # minutes, then exited without ever calling `submit_findings`. 0 of 4
    # angles, four times running.
    #
    # Only the REVIEWER is pinned here. pi is reviewer-only now; interactive
    # use is omp (omp.nix).
    [agents.pi]
    command = "pi"
    extraSpecialArgs = {
      inherit sops-nix walker nixgl drovr hunk beads mattpocock-skills cloudflare-security-audit-skill zen-browser machine;
      inherit dotfiles-private;
      inherit system;
    };
    modules = [ ./home.nix ];
  };
  linuxHome = mkHome "x86_64-linux";
in {
  homeConfigurations.utsuho = linuxHome {
    hostname = "utsuho";
    gui = true;
    gpu = "amd";
  };
  homeConfigurations.kyuusaku = linuxHome {
    hostname = "kyuusaku";
    gui = false;
    homeDir = "/local/mnt/workspace/kyuusaku";
  };
  homeConfigurations.shiori = linuxHome {
    hostname = "shiori";
    gui = true;
  };
  homeConfigurations.fujiwara = linuxHome {
    hostname = "fujiwara";
    # Headless: the box has an HDMI display wired up, but no graphical session
    # has run on it since Jun 2025. Dropping the desktop stack (hyprland,
    # waybar, walker, kanshi, portals) rather than leaving units to fail at
    # every activation. Flip back to true if it becomes a workstation again.
    gui = false;
    gpu = "amd";
  };
  homeConfigurations.chiyari = linuxHome {
    hostname = "chiyari";
    # Headless: no graphical session is planned, so isDesktop stays false and
    # home.nix hands chiyari the headless stack (emacs-nox, no hyprland/waybar,
    # pass-secret-service instead of gnome-keyring).
    gui = false;
    # Carried from the runbook's recommended profile; only matters for the btop
    # build choice. Drop if chiyari has no AMD graphics hardware at all.
    gpu = "amd";
  };
  homeConfigurations.mari = mkHome "aarch64-darwin" {
    hostname = "mari";
    gui = true;
  };

  darwinConfigurations.mari = nix-darwin.lib.darwinSystem {
    system = "aarch64-darwin";
    modules = [
      sops-nix.darwinModules.sops
        # with -- nix/wif-credentials.nix's header says why mari has one
        # identity and not two. What forces this is dropping nix-key from
        # .sops.yaml: the cluster service-account key this used to point at is
        # no longer a recipient of secrets.yaml, so a configuration still
        # aimed at it has nothing left that it can decrypt.
        #
        # The signing key stays in the human's home (0600), and this
        # activation runs as root, which can read it. That is the arrangement
        # gcp-key.json already had, so no new ordering constraint arrives with
        # the switch: both want /Users mounted, neither wants a login session.
        sops.environment = {
          GOOGLE_APPLICATION_CREDENTIALS = "${import ./nix/wif-credentials.nix {
            inherit pkgs lib;
            hostname = "mari";
            keyFile = "/Users/sauyon/.config/ko/wif.pem";
            # Darwin has no TPM at all, which is why home.nix keeps wifTpmHosts
            # as a list separate from wifHosts.
            useTpm = false;
            audience = (import "${dotfiles-private}/endpoints.nix").wifAudience;
          }}";
          # Required by Google's auth library for executable-sourced credentials.
          # The config above is a read-only store path, so this is a constraint,
          # not a risk.
          GOOGLE_EXTERNAL_ACCOUNT_ALLOW_EXECUTABLES = "1";
        };
        # Human key(s). With the OIDC gate active, its always-accept
        # AuthorizedKeysCommand (not this file) decides the publickey stage for
        # the `sauyon` login; the builder carve-out is handled separately
        # (sshOidcBuilderKey, below).
        sops.secrets."ssh-authorized-keys-sauyon" = {
          mode = "0644";

